import{_ as e,c as r,o as p,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"40、【解】 坎下震上","description":"周易尚氏学 - 40、【解】 坎下震上","frontmatter":{"title":"40、【解】 坎下震上","description":"周易尚氏学 - 40、【解】 坎下震上"},"headers":[],"relativePath":"zh/classics/shangshi/045.md","filePath":"zh/classics/shangshi/045.md"}'),i={name:"zh/classics/shangshi/045.md"};function s(t,a,l,n,c,d){return p(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_40、【解】-坎下震上" tabindex="-1">40、【解】 坎下震上 <a class="header-anchor" href="#_40、【解】-坎下震上" aria-label="Permalink to “40、【解】 坎下震上”">​</a></h1><p>震出险故曰解。归藏作荔。荔与离通。上林赋。答（上草）还离支。离支即荔支。千禄字书。离支。俗作荔支。是离荔音同通用。离即解也。义与周易同。坤位西南。四居坤初。前临重阴、阳得阴则通。故利西南。五得敌。故不利往。来复于二。各当其位。故曰其来复吉。有攸往。谓二往五。夙早也。礼记孔子间居。夙夜基命有密。疏夙即听也。听明也。二坎为夜。五震为晨。二往五则由夜及晨而天明矣。明故吉也。旧解于吉之故。皆言早往得位故吉。而王注诂夙为速尤误。岂知诗书皆以夙与夜对言。夙为早者。言早晨也。非速也。</p><p>彖曰。解。险以动。动而免乎险。解。解利西南。往得众也。无所往。其来复吉。乃得中也。有攸往夙吉。往有功也。天地解而雷雨作。雷雨作而百果草木皆甲坼。解之时大矣哉。</p><p>坎险震动。震在外。动而出险。故曰解。六五前遇阴。故曰无所往。来居二。居中当位。故吉。九二往居五。故有功。雷震坎雨。是天地解也。震为春。为百果草木。离为甲。孙星衍云。甲皮也。震动故甲拆。诉说文裂也。言草木当春。得雷雨胚胎迸裂。蓓蕾怒发。芽　潜滋。而外甲诉也。史记律书。甲者言万物剖符甲而出。又礼月令。其日甲乙。郑注云。时万物。皆解孚甲。皆甲拆之的解也。乃马陆皆读诉为宅。云根也。愚以为诉宅音同。故通用。若以宅为根。则古无此训。且草木未得雷雨之先。岂皆无孚甲无根乎。郑康成盖读与马陆同。而知其难通。故又曰。皆读如人倦之解，以济其穷。若曰皆甲宅。即解甲宅也。岂知甲宅即甲诉。不必如是穿凿。且甲可解。根如何解哉。是仍不通也。然由郑说。可悟以宅为根之非矣。乃雅丽堂刻本从惠栋校。竟改集解甲拆为甲宅。岂知苟注本作甲坼。故曰草木萌芽。萌芽。即释拆义也。若作宅。苟胡以不释。且释文早言之矣。明本集解可证也。陆道平作纂疏。不顾荀注义如何。亦改作宅。致传文与注不相应。真可异已。释文只云马陆作宅。后集荀注者。如孙堂如马国翰。皆改苟注作宅。可谓盲从。</p><h3 id="象曰。雷雨作。解。君子以教过宥罪。" tabindex="-1">象曰。雷雨作。解。君子以教过宥罪。 <a class="header-anchor" href="#象曰。雷雨作。解。君子以教过宥罪。" aria-label="Permalink to “象曰。雷雨作。解。君子以教过宥罪。”">​</a></h3><p>坎为罪过。震为解。故赦过宥罪。</p><p>初六。无咎。</p><p>承阳有应。虽失位。得无咎也。</p><h3 id="象曰。刚柔之际。义无咎也。" tabindex="-1">象曰。刚柔之际。义无咎也。 <a class="header-anchor" href="#象曰。刚柔之际。义无咎也。" aria-label="Permalink to “象曰。刚柔之际。义无咎也。”">​</a></h3><p>际交也。言初承阳。刚柔交际。故义得无咎。</p><p>九二。田获三狐。得黄矢。贞吉。</p><p>坎为狐。坎陷故为获。二应在五。五震为田猎。数三。故曰田获三狐。坎为矢。互离色黄。故曰得黄矢。贞吉者。卜问吉也。诸家皆以离为矢。离虽为甲兵。然若斧象则专属兑。矢则专象坎。坎为棘为匕为直为穿。故为矢。经从未以离为矢。</p><h3 id="象曰。九二贞吉。得中道也。" tabindex="-1">象曰。九二贞吉。得中道也。 <a class="header-anchor" href="#象曰。九二贞吉。得中道也。" aria-label="Permalink to “象曰。九二贞吉。得中道也。”">​</a></h3><p>离为道。二中位。故曰中道。</p><p>六三。负且乘。致寇至。贞吝。</p><p>三不当位。坎为车。三在车上。故曰乘。上震向外视之艮。艮为负何。故曰负且乘。坎为寇。三上下皆坎。故曰致寇至。古者君子方得乘车。若负戴则为小人之事。今负且乘焉。望之不似。则盗贼从而生心。故曰致寇至。言招致使来也。致卜问吝矣。贞吝与上贞吉为对文。故夫从虞氏以贞吉为之正者非也。</p><h3 id="象曰。负且乘。亦可且也。自我致戎。又谁咎也。" tabindex="-1">象曰。负且乘。亦可且也。自我致戎。又谁咎也。 <a class="header-anchor" href="#象曰。负且乘。亦可且也。自我致戎。又谁咎也。" aria-label="Permalink to “象曰。负且乘。亦可且也。自我致戎。又谁咎也。”">​</a></h3><p>说文戎兵也。寇至故谓致戎。</p><p>九四。解而拇。朋至斯孚。</p><p>拇。陆绩云。足大指也。王肃云。手大指。手指于震象不合。故陆注是也。震为足。四前遇重阴。阳遇阴则通。故曰解而拇。言利往也。复家云。朋来无咎。阴以阳为朋。九四前遇重阴。下乘阴。阴孚于阳。故曰朋至斯孚。言上下阴其共于四也。彖传谓往得众。指此爻也。旧解皆从虞翻说。谓四阳从初。下兑故朋至斯军。致孚义全晦。</p><h3 id="象曰。解而拇。未当位也。" tabindex="-1">象曰。解而拇。未当位也。 <a class="header-anchor" href="#象曰。解而拇。未当位也。" aria-label="Permalink to “象曰。解而拇。未当位也。”">​</a></h3><p>解而拇。前进也。四失位。进至五则当位矣。申解而拇之故也。</p><p>六五。君子维有解。吉。有孚于小人。</p><p>震为君子谓四。君子维有解。言四宜升五。当位而吉。小人谓阴。四升五成坎。坎上下皆阴。有孚维心亨。故曰有率于小人。</p><h3 id="象曰。君子有解。小人退也。" tabindex="-1">象曰。君子有解。小人退也。 <a class="header-anchor" href="#象曰。君子有解。小人退也。" aria-label="Permalink to “象曰。君子有解。小人退也。”">​</a></h3><p>君子有解。谓九四升五。小人退。谓五退居四。释爻义可谓至明白矣。</p><p>上六。公用射隼于高墉之上。获之无不利。</p><p>震为公为射为隼。伏龚为塘为高。、六居卖上。故射隼于高墉之上。盖卦为重坎。上六履重坎之上。动作如意。故获之无不利也。震射左氏象。震为鸿鹄故为隼。俱见易林。详焦氏易诂。</p><h3 id="象曰。公用射隼。以解悖也。" tabindex="-1">象曰。公用射隼。以解悖也。 <a class="header-anchor" href="#象曰。公用射隼。以解悖也。" aria-label="Permalink to “象曰。公用射隼。以解悖也。”">​</a></h3><p>坎为悖。上六居重坎之外。故曰解悖。</p>',30)])])}const m=e(i,[["render",s]]);export{_ as __pageData,m as default};
